// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// PostAuthSession Open a session from a Privy access token.
	// (POST /v1/auth/session)
	PostAuthSession(ctx context.Context, request PostAuthSessionRequestObject) (PostAuthSessionResponseObject, error)
	// DeleteDevXLink Remove a dev user's fake X account.
	// (DELETE /v1/dev/me/x-link)
	DeleteDevXLink(ctx context.Context, request DeleteDevXLinkRequestObject) (DeleteDevXLinkResponseObject, error)
	// PostDevXLink Link a fake X account to a dev user.
	// (POST /v1/dev/me/x-link)
	PostDevXLink(ctx context.Context, request PostDevXLinkRequestObject) (PostDevXLinkResponseObject, error)
	// GetHandleAvailability Check whether the caller can claim a handle.
	// (GET /v1/handles/{handle}/availability)
	GetHandleAvailability(ctx context.Context, request GetHandleAvailabilityRequestObject) (GetHandleAvailabilityResponseObject, error)
	// DeleteMe Delete the signed-in user's account.
	// (DELETE /v1/me)
	DeleteMe(ctx context.Context, request DeleteMeRequestObject) (DeleteMeResponseObject, error)
	// GetMe Read the signed-in user's account.
	// (GET /v1/me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)
	// PatchMe Update the signed-in user's profile.
	// (PATCH /v1/me)
	PatchMe(ctx context.Context, request PatchMeRequestObject) (PatchMeResponseObject, error)
	// PutMeHandle Set the caller's handle.
	// (PUT /v1/me/handle)
	PutMeHandle(ctx context.Context, request PutMeHandleRequestObject) (PutMeHandleResponseObject, error)
	// PostOnboardingPhone Store the phone the caller linked in Privy.
	// (POST /v1/me/onboarding/phone)
	PostOnboardingPhone(ctx context.Context, request PostOnboardingPhoneRequestObject) (PostOnboardingPhoneResponseObject, error)
	// PostOnboardingSkip Skip an onboarding step.
	// (POST /v1/me/onboarding/skip)
	PostOnboardingSkip(ctx context.Context, request PostOnboardingSkipRequestObject) (PostOnboardingSkipResponseObject, error)
	// PostOnboardingSocials Store the X account the caller linked in Privy.
	// (POST /v1/me/onboarding/socials)
	PostOnboardingSocials(ctx context.Context, request PostOnboardingSocialsRequestObject) (PostOnboardingSocialsResponseObject, error)
	// PostProfilePhoto Upload a profile photo.
	// (POST /v1/me/profile-photo)
	PostProfilePhoto(ctx context.Context, request PostProfilePhotoRequestObject) (PostProfilePhotoResponseObject, error)
	// SearchUsers Search people by handle or display name.
	// (GET /v1/users)
	SearchUsers(ctx context.Context, request SearchUsersRequestObject) (SearchUsersResponseObject, error)
	// GetUser Read a user's public profile.
	// (GET /v1/users/{id})
	GetUser(ctx context.Context, request GetUserRequestObject) (GetUserResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

